record_types.code:
type Reply is record
   Status  : Natural := 0;
   Content : Ada.Strings.Unbounded.Unbounded_String;
end record;

subprograms.code:
function Get
  (Host         : String;
   Port         : Positive;
   Path         : String;
   Open_Timeout : Duration;
   Read_Timeout : Duration) return Reply

function Post
  (Host         : String;
   Port         : Positive;
   Path         : String;
